// ─── File: SubqueryDemo.java ───
// Demonstrates single-row, multi-row (IN), and correlated (EXISTS) subqueries.
package com.bank.subquery;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;
import java.util.logging.*;

public class SubqueryDemo {
    private static final Logger log = Logger.getLogger(SubqueryDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        BankRepository repo = new BankRepository();
        SubqueryService service = new SubqueryService(repo);

        log.info("=== SINGLE-ROW subquery: balance > AVG(balance) ===");
        service.accountsAboveAverage().forEach(id -> log.info("above-avg: " + id));

        log.info("=== MULTI-ROW subquery (IN): txns of blocked accounts ===");
        service.txnsOfBlockedAccounts().forEach(id -> log.warning("blocked txn: " + id));

        log.info("=== CORRELATED subquery (EXISTS): accounts that transacted ===");
        service.accountsWithAnyTxn().forEach(id -> log.info("transacted: " + id));
    }
}

// ─── Would be in model/Account.java ───
class Account {
    final String accountId, holderName; final BigDecimal balance;
    Account(String id, String name, BigDecimal bal) {
        this.accountId = id; this.holderName = name; this.balance = bal;
    }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, accountId; final BigDecimal amount;
    Txn(String id, String acct, BigDecimal amt) {
        this.txnId = id; this.accountId = acct; this.amount = amt;
    }
}

// ─── Would be in repository/BankRepository.java ───
class BankRepository {
    List<Account> accounts() {
        return List.of(
            new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")),
            new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")),
            new Account("SAV2002", "Amit Verma",   new BigDecimal("300000")));
    }
    Set<String> blockedAccountIds() { return Set.of("CUR3001"); }
    List<Txn> txns() {
        return List.of(
            new Txn("TX1", "SAV2001", new BigDecimal("40000")),
            new Txn("TX2", "CUR3001", new BigDecimal("25000")));
    }
}

// ─── Would be in service/SubqueryService.java ───
class SubqueryService {
    private final BankRepository repo;
    SubqueryService(BankRepository repo) { this.repo = repo; }

    // SINGLE-ROW subquery: inner computes AVG, outer filters against it.
    List<String> accountsAboveAverage() {
        List<Account> all = repo.accounts();
        BigDecimal avg = all.stream().map(a -> a.balance)
            .reduce(BigDecimal.ZERO, BigDecimal::add)
            .divide(BigDecimal.valueOf(all.size()), 2, RoundingMode.HALF_UP);
        return all.stream().filter(a -> a.balance.compareTo(avg) > 0)
            .map(a -> a.accountId).toList();
    }

    // MULTI-ROW subquery (IN): membership test against the blocked set.
    List<String> txnsOfBlockedAccounts() {
        Set<String> blocked = repo.blockedAccountIds(); // inner "set"
        return repo.txns().stream()
            .filter(t -> blocked.contains(t.accountId))  // IN (...)
            .map(t -> t.txnId).toList();
    }

    // CORRELATED subquery (EXISTS): per-account existence check.
    List<String> accountsWithAnyTxn() {
        return repo.accounts().stream()
            .filter(a -> repo.txns().stream()
                .anyMatch(t -> t.accountId.equals(a.accountId))) // EXISTS correlated on a.id
            .map(a -> a.accountId).toList();
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
